import axios from 'axios';
import fs from 'fs-extra';
import path from 'path';
import dotenv from 'dotenv';
import {PostToolUseEvent, EditToolResponse} from './types';

dotenv.config();

// 🔐 Required environment variables
const requiredEnv = ['AZURE_ORG', 'AZURE_PROJECT', 'AZURE_REPO_ID', 'AZURE_PR_ID', 'AZURE_PAT'];
for (const key of requiredEnv) {
  if (!process.env[key]) {
    throw new Error(`Missing required environment variable: ${key}`);
  }
}

const AZURE_ORG = process.env.AZURE_ORG!;
const AZURE_PROJECT = process.env.AZURE_PROJECT!;
const REPO_ID = process.env.AZURE_REPO_ID!;
const PULL_REQUEST_ID = process.env.AZURE_PR_ID!;
const TEMP_DIR = './temp';

const authHeader = {
  headers: {
    Authorization: `Basic ${Buffer.from(`:${process.env.AZURE_PAT}`).toString('base64')}`,
  },
};

interface ChangedFile {
  path: string;
  changeType: string;
}

interface LineChange {
  lineNumber: number;
  content: string;
  type: 'added' | 'deleted' | 'modified';
}

interface FileLineChanges {
  filePath: string;
  changeType: string;
  addedLines: LineChange[];
  deletedLines: LineChange[];
  modifiedLines: LineChange[];
}

interface AiChange {
  typeOfChange: 'generated' | 'deleted';
  changedLines: string;
}

interface ChangeMatchResult {
  aiChange: AiChange;
  matchedCharacters: number;
  totalCharacters: number;
  matchPercentage: number;
  matchedInFiles: string[];
}

const parseClaudeJson = async (): Promise<PostToolUseEvent[] | null> => {
  try {
    const hooklogPath = path.join(__dirname, '..', 'logs', 'hooklog.json');
    const content = await fs.readFile(hooklogPath, 'utf-8');
    const lines = content.trim().split('\n');
    const events = lines.map(line => JSON.parse(line));

    const editEvents = events.filter(event => 
      event.hook_event_name === 'PostToolUse' && event.tool_name === 'Edit'
    );

    return editEvents;
  } catch (error: any) {
    console.error(`Error parsing hooklog.json: ${error.message}`);
    return null;
  }
};

const isBinaryFile = (filePath: string): boolean => {
  return /\.(png|jpg|jpeg|gif|bmp|ico|webp|zip|rar|7z|tar|gz|exe|dll|pdf|woff|woff2|ttf|eot|mp3|mp4|avi|mov)$/i.test(filePath);
};

const findLongestCommonSubstring = (str1: string, str2: string): number => {
  const m = str1.length;
  const n = str2.length;
  const dp = Array(m + 1).fill(null).map(() => Array(n + 1).fill(0));
  let maxLength = 0;

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (str1[i - 1] === str2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
        maxLength = Math.max(maxLength, dp[i][j]);
      }
    }
  }

  return maxLength;
};

const calculateCharacterOverlap = (aiChangeText: string, prChangeText: string): number => {
  // Remove whitespace and normalize for comparison
  const normalizeText = (text: string) => text.replace(/\s+/g, ' ').trim();

  const normalizedAi = normalizeText(aiChangeText);
  const normalizedPr = normalizeText(prChangeText);

  // Find longest common substring
  const commonLength = findLongestCommonSubstring(normalizedAi, normalizedPr);

  // Also check for partial matches by splitting into words and finding matches
  const aiWords = normalizedAi.split(' ').filter(w => w.length > 2); // ignore short words
  const prWords = normalizedPr.split(' ').filter(w => w.length > 2);

  let wordMatchChars = 0;
  aiWords.forEach(aiWord => {
    prWords.forEach(prWord => {
      if (aiWord === prWord) {
        wordMatchChars += aiWord.length;
      } else if (aiWord.includes(prWord) || prWord.includes(aiWord)) {
        // Partial word match
        wordMatchChars += Math.min(aiWord.length, prWord.length) * 0.5;
      }
    });
  });

  return Math.max(commonLength, wordMatchChars);
};

const compareAiChangesWithPR = (aiChanges: AiChange[], prChanges: FileLineChanges[]): ChangeMatchResult[] => {
  const results: ChangeMatchResult[] = [];

  aiChanges.forEach(aiChange => {
    let totalMatchedChars = 0;
    const matchedFiles: string[] = [];
    const totalChars = aiChange.changedLines.length;

    prChanges.forEach(fileChange => {
      let fileMatches = 0;

      // Get relevant PR changes based on type
      let relevantPrLines: LineChange[] = [];

      if (aiChange.typeOfChange === 'generated') {
        // Generated text should match added lines or modified lines (new content)
        relevantPrLines = [...fileChange.addedLines, ...fileChange.modifiedLines];
      } else if (aiChange.typeOfChange === 'deleted') {
        relevantPrLines = fileChange.deletedLines;
      }

      // Compare AI change text with PR change lines
      const prChangeText = relevantPrLines.map(line => line.content).join('\n');

      if (prChangeText.trim()) {
        const matchedChars = calculateCharacterOverlap(aiChange.changedLines, prChangeText);

        if (matchedChars > 0) {
          fileMatches += matchedChars;
          if (!matchedFiles.includes(fileChange.filePath)) {
            matchedFiles.push(fileChange.filePath);
          }
        }
      }

      totalMatchedChars += fileMatches;
    });

    results.push({
      aiChange,
      matchedCharacters: totalMatchedChars,
      totalCharacters: totalChars,
      matchPercentage: totalChars > 0 ? (totalMatchedChars / totalChars) * 100 : 0,
      matchedInFiles: matchedFiles
    });
  });

  return results;
};

const getPullRequestCommits = async (): Promise<{ baseCommit: string; targetCommit: string }> => {
  const url = `https://dev.azure.com/${AZURE_ORG}/${AZURE_PROJECT}/_apis/git/repositories/${REPO_ID}/pullRequests/${PULL_REQUEST_ID}?api-version=7.1-preview.1`;
  const res = await axios.get(url, authHeader);
  return {
    baseCommit: res.data.lastMergeTargetCommit.commitId,
    targetCommit: res.data.lastMergeSourceCommit.commitId,
  };
};

const getChangedFiles = async (): Promise<ChangedFile[]> => {
  const iterationsUrl = `https://dev.azure.com/${AZURE_ORG}/${AZURE_PROJECT}/_apis/git/repositories/${REPO_ID}/pullRequests/${PULL_REQUEST_ID}/iterations?api-version=7.1-preview.1`;
  const iterationsRes = await axios.get(iterationsUrl, authHeader);
  const latestIterationId = iterationsRes.data.value.slice(-1)[0].id;

  const changesUrl = `https://dev.azure.com/${AZURE_ORG}/${AZURE_PROJECT}/_apis/git/repositories/${REPO_ID}/pullRequests/${PULL_REQUEST_ID}/iterations/${latestIterationId}/changes?api-version=7.1-preview.1`;
  const changesRes = await axios.get(changesUrl, authHeader);

  return changesRes.data?.changeEntries
    .map((entry: any) => ({
      path: entry.item?.path,
      changeType: entry.changeType,
    }))
    .filter((f: ChangedFile) => !!f.path && !isBinaryFile(f.path));
};

const downloadFileContent = async (filePath: string, commitId: string): Promise<string> => {
  const url = `https://dev.azure.com/${AZURE_ORG}/${AZURE_PROJECT}/_apis/git/repositories/${REPO_ID}/items?path=${encodeURIComponent(filePath)}&version=${commitId}&versionType=commit&includeContent=true&api-version=7.1-preview.1`;
  const res = await axios.get(url, authHeader);
  return res.data?.content || '';
};

// Simple LCS-based diff algorithm
const computeDiff = (originalLines: string[], modifiedLines: string[]) => {
  const m = originalLines.length;
  const n = modifiedLines.length;

  // LCS table
  const lcs = Array(m + 1).fill(null).map(() => Array(n + 1).fill(0));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (originalLines[i - 1] === modifiedLines[j - 1]) {
        lcs[i][j] = lcs[i - 1][j - 1] + 1;
      } else {
        lcs[i][j] = Math.max(lcs[i - 1][j], lcs[i][j - 1]);
      }
    }
  }

  // Backtrack to find changes
  const changes: Array<{type: 'add' | 'delete' | 'same', originalLine?: number, modifiedLine?: number, content: string}> = [];
  let i = m, j = n;

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && originalLines[i - 1] === modifiedLines[j - 1]) {
      changes.unshift({type: 'same', originalLine: i, modifiedLine: j, content: originalLines[i - 1]});
      i--; j--;
    } else if (j > 0 && (i === 0 || lcs[i][j - 1] >= lcs[i - 1][j])) {
      changes.unshift({type: 'add', modifiedLine: j, content: modifiedLines[j - 1]});
      j--;
    } else if (i > 0) {
      changes.unshift({type: 'delete', originalLine: i, content: originalLines[i - 1]});
      i--;
    }
  }

  return changes;
};

const getFileLineChanges = async (filePath: string, baseCommit: string, targetCommit: string, iterationId?: number): Promise<FileLineChanges> => {
  const result: FileLineChanges = {
    filePath,
    changeType: 'unknown',
    addedLines: [],
    deletedLines: [],
    modifiedLines: []
  };

  try {
    // Try to get the actual file content from both commits and generate our own diff
    let originalContent = '';
    let modifiedContent = '';

    try {
      originalContent = await downloadFileContent(filePath, baseCommit);
    } catch (err) {
      // File might not exist in base commit (new file)
      originalContent = '';
    }

    try {
      modifiedContent = await downloadFileContent(filePath, targetCommit);
    } catch (err) {
      // File might not exist in target commit (deleted file)
      modifiedContent = '';
    }

    const originalLines = originalContent ? originalContent.split('\n') : [];
    const modifiedLines = modifiedContent ? modifiedContent.split('\n') : [];

    // Determine change type
    if (originalLines.length === 0 && modifiedLines.length > 0) {
      result.changeType = 'add';
      // All lines are added
      modifiedLines.forEach((line, index) => {
        result.addedLines.push({
          lineNumber: index + 1,
          content: line,
          type: 'added'
        });
      });
    } else if (originalLines.length > 0 && modifiedLines.length === 0) {
      result.changeType = 'delete';
      // All lines are deleted
      originalLines.forEach((line, index) => {
        result.deletedLines.push({
          lineNumber: index + 1,
          content: line,
          type: 'deleted'
        });
      });
    } else {
      result.changeType = 'edit';

      // Use proper diff algorithm
      const changes = computeDiff(originalLines, modifiedLines);

      changes.forEach(change => {
        if (change.type === 'add') {
          result.addedLines.push({
            lineNumber: change.modifiedLine || 0,
            content: change.content,
            type: 'added'
          });
        } else if (change.type === 'delete') {
          result.deletedLines.push({
            lineNumber: change.originalLine || 0,
            content: change.content,
            type: 'deleted'
          });
        }
      });
    }

    return result;

  } catch (error: any) {
    console.warn(`Failed to get diff for ${filePath}:`, error.message);
    return result;
  }
};

const processChangedFiles = async (
  files: ChangedFile[],
  baseCommit: string,
  targetCommit: string
) => {
  const allFileChanges: FileLineChanges[] = [];

  for (const file of files) {
    try {
      const content = await downloadFileContent(file.path, targetCommit);
      const lineChanges = await getFileLineChanges(file.path, baseCommit, targetCommit);

      const filePath = path.join(TEMP_DIR, file.path);
      const changesPath = path.join(TEMP_DIR, file.path + '.changes.json');

      await fs.outputFile(filePath, content);
      await fs.outputFile(changesPath, JSON.stringify(lineChanges, null, 2));

      allFileChanges.push(lineChanges);

      console.log(`📄 File: ${file.path} [${lineChanges.changeType}]`);
      console.log(`  ➕ Added lines: ${lineChanges.addedLines.length}`);
      console.log(`  ➖ Deleted lines: ${lineChanges.deletedLines.length}`);
      console.log(`  ✏️ Modified lines: ${lineChanges.modifiedLines.length}`);

      if (lineChanges.addedLines.length > 0) {
        console.log(`  Added lines:`);
        lineChanges.addedLines.forEach(line => 
          console.log(`    +${line.lineNumber}: ${line.content.substring(0, 100)}`)
        );
      }

      if (lineChanges.deletedLines.length > 0) {
        console.log(`  Deleted lines:`);
        lineChanges.deletedLines.forEach(line => 
          console.log(`    -${line.lineNumber}: ${line.content.substring(0, 100)}`)
        );
      }

      if (lineChanges.modifiedLines.length > 0) {
        console.log(`  Modified lines:`);
        lineChanges.modifiedLines.forEach(line => 
          console.log(`    ~${line.lineNumber}: ${line.content.substring(0, 100)}`)
        );
      }

      console.log('');
    } catch (err: any) {
      console.warn(`⚠️ Error processing ${file.path}: ${err.message}`);
    }
  }

  const summaryPath = path.join(TEMP_DIR, 'pr-line-changes-summary.json');
  await fs.outputFile(summaryPath, JSON.stringify(allFileChanges, null, 2));
  console.log(`📊 Summary saved to: ${summaryPath}`);

  return allFileChanges;
};

(async () => {
  try {
    await fs.ensureDir(TEMP_DIR);
    const { baseCommit, targetCommit } = await getPullRequestCommits();
