// Simple LCS-based diff algorithm
const computeDiff = (originalLines: string[], modifiedLines: string[]) => {
  const m = originalLines.length;
  const n = modifiedLines.length;

  // LCS table
  const lcs = Array(m + 1).fill(null).map(() => Array(n + 1).fill(0));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (originalLines[i - 1] === modifiedLines[j - 1]) {
        lcs[i][j] = lcs[i - 1][j - 1] + 1;
      } else {
        lcs[i][j] = Math.max(lcs[i - 1][j], lcs[i][j - 1]);
      }
    }
  }

  // Backtrack to find changes
  const changes: Array<{type: 'add' | 'delete' | 'same', originalLine?: number, modifiedLine?: number, content: string}> = [];
  let i = m, j = n;

  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && originalLines[i - 1] === modifiedLines[j - 1]) {
      changes.unshift({type: 'same', originalLine: i, modifiedLine: j, content: originalLines[i - 1]});
      i--; j--;
    } else if (j > 0 && (i === 0 || lcs[i][j - 1] >= lcs[i - 1][j])) {
      changes.unshift({type: 'add', modifiedLine: j, content: modifiedLines[j - 1]});
      j--;
    } else if (i > 0) {
      changes.unshift({type: 'delete', originalLine: i, content: originalLines[i - 1]});
      i--;
    }
  }

  return changes;
};

const getFileLineChanges = async (filePath: string, baseCommit: string, targetCommit: string, iterationId?: number): Promise<FileLineChanges> => {
  const result: FileLineChanges = {
    filePath,
    changeType: 'unknown',
    addedLines: [],
    deletedLines: [],
    modifiedLines: []
  };

  try {
    // Try to get the actual file content from both commits and generate our own diff
    let originalContent = '';
    let modifiedContent = '';

    try {
      originalContent = await downloadFileContent(filePath, baseCommit);
    } catch (err) {
      // File might not exist in base commit (new file)
      originalContent = '';
    }

    try {
      modifiedContent = await downloadFileContent(filePath, targetCommit);
    } catch (err) {
      // File might not exist in target commit (deleted file)
      modifiedContent = '';
    }

    const originalLines = originalContent ? originalContent.split('\n') : [];
    const modifiedLines = modifiedContent ? modifiedContent.split('\n') : [];

    // Determine change type
    if (originalLines.length === 0 && modifiedLines.length > 0) {
      result.changeType = 'add';
      // All lines are added
      modifiedLines.forEach((line, index) => {
        result.addedLines.push({
          lineNumber: index + 1,
          content: line,
          type: 'added'
        });
      });
    } else if (originalLines.length > 0 && modifiedLines.length === 0) {
      result.changeType = 'delete';
      // All lines are deleted
      originalLines.forEach((line, index) => {
        result.deletedLines.push({
          lineNumber: index + 1,
          content: line,
          type: 'deleted'
        });
      });
    } else {
      result.changeType = 'edit';

      // Use proper diff algorithm
      const changes = computeDiff(originalLines, modifiedLines);

      changes.forEach(change => {
        if (change.type === 'add') {
          result.addedLines.push({
            lineNumber: change.modifiedLine || 0,
            content: change.content,
            type: 'added'
          });
        } else if (change.type === 'delete') {
          result.deletedLines.push({
            lineNumber: change.originalLine || 0,
            content: change.content,
            type: 'deleted'
          });
        }
      });
    }

    return result;

  } catch (error: any) {
    console.warn(`Failed to get diff for ${filePath}:`, error.message);
    return result;
  }
};

