    modifiedLines: []
  };

  try {
    // Try to get the actual file content from both commits and generate our own diff
    let originalContent = '';
    let modifiedContent = '';

    try {
      originalContent = await downloadFileContent(filePath, baseCommit);
    } catch (err) {
      // File might not exist in base commit (new file)
      originalContent = '';
    }

    try {
      modifiedContent = await downloadFileContent(filePath, targetCommit);
    } catch (err) {
      // File might not exist in target commit (deleted file)
      modifiedContent = '';
    }

    const originalLines = originalContent ? originalContent.split('\n') : [];
    const modifiedLines = modifiedContent ? modifiedContent.split('\n') : [];

    // Determine change type
    if (originalLines.length === 0 && modifiedLines.length > 0) {
      result.changeType = 'add';
      // All lines are added
      modifiedLines.forEach((line, index) => {
        result.addedLines.push({
          lineNumber: index + 1,
          content: line,
          type: 'added'
        });
      });
    } else if (originalLines.length > 0 && modifiedLines.length === 0) {
      result.changeType = 'delete';
      // All lines are deleted
      originalLines.forEach((line, index) => {
        result.deletedLines.push({
          lineNumber: index + 1,
          content: line,
          type: 'deleted'
        });
      });
    } else {
      result.changeType = 'edit';

      // Use proper diff algorithm
      const changes = computeDiff(originalLines, modifiedLines);

      changes.forEach(change => {
        if (change.type === 'add') {
          result.addedLines.push({
            lineNumber: change.modifiedLine || 0,
            content: change.content,
            type: 'added'
          });
        } else if (change.type === 'delete') {
          result.deletedLines.push({
            lineNumber: change.originalLine || 0,
            content: change.content,
            type: 'deleted'
          });
        }
      });
    }

    return result;

  } catch (error: any) {
    console.warn(`Failed to get diff for ${filePath}:`, error.message);
    return result;
  }
};

const processChangedFiles = async (
  files: ChangedFile[],
  baseCommit: string,
  targetCommit: string
) => {
  const allFileChanges: FileLineChanges[] = [];

  for (const file of files) {
    try {
      const content = await downloadFileContent(file.path, targetCommit);
      const lineChanges = await getFileLineChanges(file.path, baseCommit, targetCommit);

      const filePath = path.join(TEMP_DIR, file.path);
      const changesPath = path.join(TEMP_DIR, file.path + '.changes.json');

      await fs.outputFile(filePath, content);
      await fs.outputFile(changesPath, JSON.stringify(lineChanges, null, 2));

      allFileChanges.push(lineChanges);

      console.log(`📄 File: ${file.path} [${lineChanges.changeType}]`);
      console.log(`  ➕ Added lines: ${lineChanges.addedLines.length}`);
      console.log(`  ➖ Deleted lines: ${lineChanges.deletedLines.length}`);
      console.log(`  ✏️ Modified lines: ${lineChanges.modifiedLines.length}`);

      if (lineChanges.addedLines.length > 0) {
        console.log(`  Added lines:`);
        lineChanges.addedLines.forEach(line => 
          console.log(`    +${line.lineNumber}: ${line.content.substring(0, 100)}`)
        );
      }

      if (lineChanges.deletedLines.length > 0) {
        console.log(`  Deleted lines:`);
        lineChanges.deletedLines.forEach(line => 
          console.log(`    -${line.lineNumber}: ${line.content.substring(0, 100)}`)
        );
      }

      if (lineChanges.modifiedLines.length > 0) {
        console.log(`  Modified lines:`);
        lineChanges.modifiedLines.forEach(line => 
          console.log(`    ~${line.lineNumber}: ${line.content.substring(0, 100)}`)
        );
      }

      console.log('');
    } catch (err: any) {
      console.warn(`⚠️ Error processing ${file.path}: ${err.message}`);
    }
  }

  const summaryPath = path.join(TEMP_DIR, 'pr-line-changes-summary.json');
  await fs.outputFile(summaryPath, JSON.stringify(allFileChanges, null, 2));
  console.log(`📊 Summary saved to: ${summaryPath}`);

  return allFileChanges;
};

const displayClaudeEvents = (events: PostToolUseEvent[]) => {
  console.log('\n📊 Claude Events:');
  console.log('================');
  events?.forEach(claudeEvent => {
    const editResponse = claudeEvent.tool_response as EditToolResponse;
    if (editResponse.structuredPatch) {
      console.log(`File: ${editResponse.filePath}`);
      editResponse.structuredPatch.forEach(patch => {
        console.log(`Lines ${patch.oldStart}-${patch.oldStart + patch.oldLines - 1} -> ${patch.newStart}-${patch.newStart + patch.newLines - 1}:`);
      });
    }
  });
};

const displayClaudeSummary = (changes: ClaudeChangeAnalysis[]) => {
  console.log('\n📊 Claude Summary:');
  console.log('================');
  changes.forEach(change => {
    console.log(`File: ${change.filePath}`);
    console.log(`Add/Edit/Delete: ${change.addedLineCount}/${change.modifiedLineCount}/${change.deletedLineCount}`);
  });
};

const displayPrSummary = (fileChanges: FileLineChanges[]) => {
  console.log('\n📊 PR Summary:');
  console.log('================');
  fileChanges.forEach(fileChange => {
    const totalLines = fileChange.addedLines.length + fileChange.deletedLines.length + fileChange.modifiedLines.length;
    console.log(`${fileChange.filePath} [${fileChange.changeType}] - ${totalLines} lines changed`);
  });
};

const displayAiAnalysis = (results: ChangeMatchResult[]) => {
  console.log('\n🤖 AI Change Analysis:');
  console.log('=====================');
  results.forEach((result, index) => {
    console.log(`\nAI Change ${index + 1} [${result.aiChange.typeOfChange}]:`);
    console.log(`  Matched: ${result.matchedCharacters}/${result.totalCharacters} characters (${result.matchPercentage.toFixed(1)}%)`);
    console.log(`  Files: ${result.matchedInFiles.length > 0 ? result.matchedInFiles.join(', ') : 'No matches'}`);
    if (result.matchPercentage > MATCH_CONFIDENCE.HIGH_THRESHOLD) {
      console.log(`  ✅ High confidence match`);
    } else if (result.matchPercentage > MATCH_CONFIDENCE.PARTIAL_THRESHOLD) {
      console.log(`  ⚠️ Partial match`);
    } else {
      console.log(`  ❌ Low/no match`);
    }
  });
};

const main = async () => {
  try {
    await fs.ensureDir(TEMP_DIR);
    const { baseCommit, targetCommit } = await getPullRequestCommits();
    const changedFiles = await getChangedFiles();
    const allFileChanges = await processChangedFiles(changedFiles, baseCommit, targetCommit);

    const hookEvents = await parseClaudeHookLog(); 
    const claudeChanges = scanClaudeChanges(hookEvents); 

    displayClaudeEvents(hookEvents);
    displayClaudeSummary(claudeChanges);
    displayPrSummary(allFileChanges);

    const matchResults = compareClaudeChangesWithPRChanges([], allFileChanges);
    displayAiAnalysis(matchResults);

  } catch (err: any) {
    console.error(`❌ Fatal error: ${err.message}`);
  }
};

main();

